const detachedObservations = new Set<string>();

/** [changmen 扩展] 取消队列只停止新下注；已发送的原单仍核验并绑定，不写回新队列。 */
function continueDetachedObservation(ctx: VenueJbSettlementContext): void {
  const { account, result } = ctx;
  const orderId = String(result.orderId ?? "").trim();
  if (!orderId)
    return;
  const session = getAuthSessionVersion();
  const key = `${session}:${account.accountId}:${orderId}`;
  if (detachedObservations.has(key))
    return;
  detachedObservations.add(key);
  const accountId = account.accountId;
  const provider = account.provider;
  const token = account.token;
  const gateway = account.gateway;
  const run = async () => {
    const current = useAccountStore().findAccount(accountId);
    if (!isAuthSessionCurrent(session) || !current || current.provider !== provider
      || current.token !== token || current.gateway !== gateway) {
      detachedObservations.delete(key);
      return;
    }
    let pending = true;
    try {
      pending = (await applyVenueJbSettlementOutcome(ctx)) === "pending";
    }
    catch { /* 查询失败继续核对原单，不触发新 POST。 */ }
    if (pending)
      setTimeout(() => { void run(); }, 1_000);
    else
      detachedObservations.delete(key);
  };
  setTimeout(() => { void run(); }, 1_000);
}

